def _quantize_nmf_number(value, name, positive=False):
    """Quantize an NMF value to its canonical 12-decimal JSON form.

    The value must have type exactly ``int`` or ``float`` (booleans and
    subclasses rejected); a float must be finite and (when ``positive``)
    strictly greater than zero, while an int may have arbitrary magnitude
    but must be non-negative (or strictly positive). A negative value is
    rejected before quantization, so even a tiny negative value that
    would quantize to zero raises ValueError. Quantization is
    ``Decimal(str(v)).quantize(1E-12, ROUND_HALF_UP)`` with the value
    never passed through ``float`` first; negative zero normalizes to
    ``0.000000000000``. The fixed text must convert back with ``float``
    to a finite value, and strictly positive parameters must remain
    strictly positive after quantization.
    """
    if isinstance(value, bool) or type(value) not in (int, float):
        raise ValueError("%s must be a finite non-boolean int or float" % name)
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError(
                "%s must be a finite non-boolean int or float" % name
            )
        if positive and value <= 0.0:
            raise ValueError("%s must be greater than 0" % name)
    elif positive and value <= 0:
        raise ValueError("%s must be greater than 0" % name)
    if value < 0:
        raise ValueError("%s must be non-negative" % name)
    token = str(value)
    try:
        with localcontext() as ctx:
            ctx.prec = max(400, len(token) + 50)
            quantized = Decimal(token).quantize(
                _QUANTUM12, rounding=ROUND_HALF_UP
            )
    except (ArithmeticError, ValueError) as exc:
        raise ValueError(
            "%s must be a finite non-boolean int or float" % name
        ) from exc
    if positive and quantized <= 0:
        raise ValueError(
            "%s must remain positive after quantization to 12 decimals"
            % name
        )
    if quantized < 0:
        raise ValueError("%s must be non-negative" % name)
    text = "0.000000000000" if quantized == 0 else format(quantized, "f")
    try:
        converted = float(text)
    except (OverflowError, ValueError) as exc:
        raise ValueError(
            "%s fixed text must convert to a finite float" % name
        ) from exc
    if not math.isfinite(converted):
        raise ValueError(
            "%s fixed text must convert to a finite float" % name
        )
    return text

def _load_nmf(pairs):
    keys = tuple(key for key, _ in pairs)
    if keys != _SERIAL_KEYS_NMF:
        raise ValueError(
            "NMF JSON must have exactly the serialized keys "
            "in the serialized order"
        )
    data = _convert(pairs)

    class_name = data["class"]
    if not isinstance(class_name, str) or class_name != "NMF":
        raise ValueError('class must be "NMF"')

    n_components = _expect_int(data["n_components"], "n_components")
    max_iter = _expect_int(data["max_iter"], "max_iter")
    seed = _expect_int(data["seed"], "seed")
    n_features = _expect_int(data["n_features_in"], "n_features_in")
    if n_components <= 0:
        raise ValueError("n_components must be greater than 0")
    if max_iter <= 0:
        raise ValueError("max_iter must be greater than 0")
    if n_features <= 0:
        raise ValueError("n_features_in must be greater than 0")

    tol = _expect_fixed12(data["tol"], "tol")
    if tol <= 0.0:
        raise ValueError("tol must be greater than 0")

    components_node = data["components"]
    if not isinstance(
        components_node, list
    ) or len(components_node) != n_components:
        raise ValueError("components must have n_components rows")
    components = []
    for row in components_node:
        if not isinstance(row, list) or len(row) != n_features:
            raise ValueError(
                "components must be a rectangular n_components by "
                "n_features_in matrix"
            )
        parsed_row = [
            _expect_fixed12(value, "components element") for value in row
        ]
        for value in parsed_row:
            if value < 0.0:
                raise ValueError("components elements must be non-negative")
        components.append(parsed_row)

    model = NMF(
        n_components=n_components,
        max_iter=max_iter,
        tol=tol,
        seed=seed,
    )
    # Fresh nested lists so the fitted state never shares storage with the
    # parsed payload.
    model.components_ = [list(row) for row in components]
    model.n_features_in_ = n_features
    return model


def _load_knn_regressor(pairs):
    keys = tuple(key for key, _ in pairs)
    if keys != _SERIAL_KEYS_KNN_REGRESSOR:
        raise ValueError(
            "KNeighborsRegressor JSON must have exactly the serialized "
            "keys in the serialized order"
        )
    data = _convert(pairs)

    class_name = data["class"]
    if not isinstance(class_name, str) or class_name != "KNeighborsRegressor":
        raise ValueError('class must be "KNeighborsRegressor"')

    n_neighbors = _expect_int(data["n_neighbors"], "n_neighbors")
    if n_neighbors < 1:
        raise ValueError("n_neighbors must be a positive integer")

    weights = data["weights"]
    if not isinstance(weights, str) or weights not in ("uniform", "distance"):
        raise ValueError('weights must be "uniform" or "distance"')

    n_features = _expect_int(data["n_features_in"], "n_features_in")
    if n_features < 1:
        raise ValueError("n_features_in must be a positive integer")

    x_node = data["X"]
    if not isinstance(x_node, list) or len(x_node) == 0:
        raise ValueError("X must be a non-empty array of rows")
    if len(x_node) < n_neighbors:
        raise ValueError("X must have at least n_neighbors rows")
    X = []
    for row in x_node:
        if not isinstance(row, list) or len(row) != n_features:
            raise ValueError("every X row must have length n_features_in")
        X.append([_expect_fixed(v, "X element") for v in row])

    y_node = data["y"]
    if not isinstance(y_node, list) or len(y_node) != len(X):
        raise ValueError("y must be an array with the same length as X")
    y = [_expect_fixed(v, "y element") for v in y_node]

    model = KNeighborsRegressor(n_neighbors=n_neighbors, weights=weights)
    model._X = X
    model._y = y
    model._width = n_features
    return model


