        except Exception as exc:
            raise ValueError("malformed serialized model") from exc
    if class_entry == "StandardScaler":
        try:
            return _load_scaler(pairs)
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError("malformed serialized model") from exc
    if class_entry == "DecisionTreeClassifier":
        try:
            return _load_tree(pairs)
        except ValueError:
