    if class_entry == "ExtraTreesClassifier":
        try:
            return _load_forest(pairs, "ExtraTreesClassifier")
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError("malformed serialized model") from exc
    if class_entry == "RandomForestRegressor":
        try:
